mapper.insert:
insert into PBC_COL_REPORT_BALANCE (DETAILUUID,
  PROPERTYCODE, CNY, USD_TO_CNY,
  EUR_TO_CNY, GBP_TO_CNY, JPY_TO_CNY,
  OTH_TO_CNY, TOTAL, REPORTUUID
  )
values (#{detailuuid,jdbcType=CHAR},
  #{propertycode,jdbcType=VARCHAR}, #{cny,jdbcType=DECIMAL}, #{usdToCny,jdbcType=DECIMAL},
  #{eurToCny,jdbcType=DECIMAL}, #{gbpToCny,jdbcType=DECIMAL}, #{jpyToCny,jdbcType=DECIMAL},
  #{othToCny,jdbcType=DECIMAL}, #{total,jdbcType=DECIMAL}, #{reportuuid,jdbcType=CHAR}
  )

mapper.update:
update ZG05_PBC_COL_REPORT sub set sub.SEND_STATUS = '03', sub.submit_time = NOW(), sub.UPDATE_TIME = NOW() where
sub.TERMID=#{item.termid,jdbcType=VARCHAR}
and sub.SEND_STATUS ='01'

update ZG05_PBC_COL_REPORT sub set sub.SEND_STATUS = '01', sub.submit_time = NOW(), sub.UPDATE_TIME = NOW() where
sub.TERMID=#{item.termid,jdbcType=VARCHAR}
and sub.SEND_STATUS ='03'
